sp_widget.client_script:
function($scope, $rootScope) {
    var chartAmortizacaoCloneInstance = null;

    $scope.anoSelecionadoAmortizacaoClone = "";
    $scope.exibirGraficoAmortizacaoClone = false;
    $scope.tipoGraficoAmortizacaoClone = 'line'; // padrão: linha
    $scope.dadosAmortizacaoClone = [];

    function carregarDadosAmortizacaoClone() {
    var filtros = {
        ano: $scope.anoSelecionadoAmortizacaoClone || ""
    };

    $scope.server.get(filtros).then(function(response) {
        $scope.dadosAmortizacaoClone = response.data.dadosAmortizacaoClone || [];

        setTimeout(function () {
            inicializarGraficoAmortizacaoClone($scope.dadosAmortizacaoClone);
        }, 300); // 300ms de atraso
    });
}


    $rootScope.$on('filtroAnoIndicadoresSelecionado', function(event, ano) {
        $scope.anoSelecionadoAmortizacaoClone = ano;

        // Muda o gráfico para barra se ano for selecionado, senão linha
        $scope.tipoGraficoAmortizacaoClone = ano ? 'bar' : 'line';

        carregarDadosAmortizacaoClone();
    });

    carregarDadosAmortizacaoClone();

    function inicializarGraficoAmortizacaoClone(listaAmortizacaoClone) {
        if (!listaAmortizacaoClone || listaAmortizacaoClone.length === 0) {
            if (chartAmortizacaoCloneInstance) {
                chartAmortizacaoCloneInstance.destroy();
                chartAmortizacaoCloneInstance = null;
            }
            $scope.exibirGraficoAmortizacaoClone = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoAmortizacaoClone = true;
        $scope.$applyAsync();

        var labelsClone = [];
        var amortizacaoExternaCloneData = [];
        var amortizacaoInternaCloneData = [];

        listaAmortizacaoClone.forEach(function(item) {
            labelsClone.push(item.ano);
            amortizacaoExternaCloneData.push(item.amortizacaoExterna);
            amortizacaoInternaCloneData.push(item.amortizacaoInterna);
        });

        var canvas = document.getElementById('graficoAmortizacaoClone');
        if (!canvas) {
            console.error("Elemento canvas 'graficoAmortizacaoClone' não encontrado.");
            return;
        }

        var ctx = canvas.getContext('2d');

        if (chartAmortizacaoCloneInstance) {
            chartAmortizacaoCloneInstance.destroy();
        }

        chartAmortizacaoCloneInstance = new Chart(ctx, {
            type: $scope.tipoGraficoAmortizacaoClone,
            data: {
                labels: labelsClone,
                datasets: [
                    {
                        label: 'Amortização Externa',
                        data: amortizacaoExternaCloneData,
                        borderColor: '#4A75B1',
                        backgroundColor: $scope.tipoGraficoAmortizacaoClone === 'bar' ? '#4A75B1' : 'transparent',
                        borderWidth: 2,
                        borderDash: $scope.tipoGraficoAmortizacaoClone === 'line' ? [6, 4] : [],
                        fill: false,
                        tension: 0.4,
                        pointRadius: 3,
                        yAxisID: 'y'
                    },
                    {
                        label: 'Amortização Interna',
                        data: amortizacaoInternaCloneData,
                        borderColor: '#6BB7F0',
                        backgroundColor: $scope.tipoGraficoAmortizacaoClone === 'bar' ? '#6BB7F0' : 'transparent',
                        borderWidth: 2,
                        fill: false,
                        tension: 0.4,
                        pointRadius: 3,
                        yAxisID: 'y'
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Ano'
                        }
                    },
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Valores (em R$)'
                        }
                    }
                },
                plugins: {
                    legend: {
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                var valor = context.parsed.y || 0;
                                var valorFormatado = valor.toFixed(2)
                                    .replace('.', ',')
                                    .replace(/\B(?=(\d{3})+(?!\d))/g, '.');
                                return context.dataset.label + ': R$ ' + valorFormatado;
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    var anoFiltroClone = input.ano || "";

    var grClone = new GlideRecord('x_sded9_portal_t_0_u_amortizacao_juros');
    if (anoFiltroClone !== "") {
        grClone.addQuery('u_ano', anoFiltroClone);
    }
    grClone.orderBy('u_ano');
    grClone.query();

    var listaAmortizacaoClone = [];

    while (grClone.next()) {
        listaAmortizacaoClone.push({
            ano: grClone.getValue('u_ano'),
            amortizacaoExterna: parseFloat(grClone.getValue('u_amortizacao_externa')) / 1 || 0,
            amortizacaoInterna: parseFloat(grClone.getValue('u_amortizacao_interna')) / 1 || 0
        });
    }

    data.dadosAmortizacaoClone = listaAmortizacaoClone;
})();
